CREATE TABLE "application_sessions" (
  "session_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "profile_id" integer NOT NULL REFERENCES profiles(profile_id) ON DELETE CASCADE,
  "job_ad_text" text NOT NULL,
  "application_text" text NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "application_session_messages" (
  "message_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "session_id" integer NOT NULL REFERENCES application_sessions(session_id) ON DELETE CASCADE,
  "role" varchar NOT NULL CHECK ("role" IN ('user', 'assistant')),
  "content" text NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_application_sessions_profile_id
  ON application_sessions(profile_id);

CREATE INDEX idx_application_session_messages_session_id
  ON application_session_messages(session_id);